#pragma once

// Executable registry of every public declaration in src/*.hpp.
//
// src/formula_lab_gen.cpp is generated by tools/gen_formula_lab.py. It contains
// one call site per public function, the conversions from the shared lab inputs
// to that function's declared parameter types, and a formatter for its return
// value. Nothing is hand-picked: adding a declaration to a public header and
// re-running the generator adds a runnable lab entry.

#include <algorithm>
#include <cmath>
#include <complex>
#include <cstddef>
#include <random>
#include <sstream>
#include <string>
#include <type_traits>
#include <vector>

#include "json.hpp"
#include "ml.hpp"

namespace climate {

struct LabParam {
    std::string name;
    std::string type;
    std::string kind;  // number | complex | series | int_series | matrix | text | seed | enum | struct
    double default_value = 1.0;
};

struct LabFormula {
    std::size_t index = 0;
    std::string id;           // module::name
    std::string name;
    std::string module;
    std::string stage;        // 01..07
    std::string stage_label;
    std::string signature;
    std::string returns;
    std::vector<LabParam> params;

    LabFormula() = default;
    LabFormula(const LabFormula& other) { *this = other; }
    LabFormula& operator=(const LabFormula& other) = default;
};

struct LabInputs {
    std::vector<double> numbers;                     // scalar arguments, declaration order
    std::vector<double> time;                        // the active time axis
    std::vector<double> series;                      // the active time series
    std::vector<std::vector<double>> matrix;         // row-wise matrix arguments
    std::vector<std::vector<double>> square;         // square matrix (weights, covariances)
    std::string text;                                // string arguments
};

// ---------------------------------------------------------------------------
// Value formatting used by the generated call sites.
// ---------------------------------------------------------------------------
inline std::string trim_zero(std::string text) {
    if (text.find('.') == std::string::npos || text.find('e') != std::string::npos) return text;
    while (!text.empty() && text.back() == '0') text.pop_back();
    if (!text.empty() && text.back() == '.') text.pop_back();
    return text;
}

inline std::string fmt_number(double value) {
    if (!std::isfinite(value)) return std::isnan(value) ? "nan" : (value > 0 ? "inf" : "-inf");
    std::ostringstream stream;
    stream.precision(8);
    stream << value;
    return trim_zero(stream.str());
}

inline std::string fmt_integer(double value) {
    if (!std::isfinite(value)) return fmt_number(value);
    std::ostringstream stream;
    stream << static_cast<long long>(std::llround(value));
    return stream.str();
}

inline std::string fmt_text(const std::string& value) { return "\"" + value + "\""; }

inline std::string fmt_series(const std::vector<double>& values) {
    std::ostringstream stream;
    stream << "[";
    for (std::size_t i = 0; i < values.size(); ++i) {
        if (i) stream << ", ";
        if (i >= 12) {
            stream << "... " << values.size() << " values]";
            return stream.str();
        }
        stream << fmt_number(values[i]);
    }
    stream << "]";
    return stream.str();
}

template <class I>
inline std::string fmt_int_series(const std::vector<I>& values) {
    std::ostringstream stream;
    stream << "[";
    for (std::size_t i = 0; i < values.size() && i < 12; ++i) {
        if (i) stream << ", ";
        stream << values[i];
    }
    if (values.size() > 12) stream << ", ... " << values.size() << " values";
    stream << "]";
    return stream.str();
}

inline std::string fmt_matrix(const std::vector<std::vector<double>>& matrix) {
    std::ostringstream stream;
    stream << matrix.size() << "x" << (matrix.empty() ? 0 : matrix.front().size()) << " [";
    for (std::size_t r = 0; r < matrix.size() && r < 3; ++r) {
        if (r) stream << "; ";
        for (std::size_t c = 0; c < matrix[r].size() && c < 6; ++c) {
            if (c) stream << ", ";
            stream << fmt_number(matrix[r][c]);
        }
        if (matrix[r].size() > 6) stream << ", ...";
    }
    if (matrix.size() > 3) stream << "; ...";
    stream << "]";
    return stream.str();
}

inline std::string fmt_pair(const std::pair<double, double>& value) {
    return "(" + fmt_number(value.first) + ", " + fmt_number(value.second) + ")";
}

inline std::string fmt_complex_series(const std::vector<std::complex<double>>& values) {
    std::ostringstream stream;
    stream << "[";
    for (std::size_t i = 0; i < values.size() && i < 8; ++i) {
        if (i) stream << ", ";
        stream << fmt_number(values[i].real()) << (values[i].imag() < 0 ? "-" : "+")
               << fmt_number(std::fabs(values[i].imag())) << "i";
    }
    if (values.size() > 8) stream << ", ... " << values.size() << " values";
    stream << "]";
    return stream.str();
}

inline std::string fmt_enum(int value, const std::vector<std::string>& names) {
    if (value >= 0 && static_cast<std::size_t>(value) < names.size()) return names[value];
    return "enum(" + fmt_integer(value) + ")";
}

inline std::string fmt_label(const std::string& label) { return label; }

template <class T>
std::string fmt_value(const T&);
template <>
inline std::string fmt_value(const double& value) { return fmt_number(value); }
template <>
inline std::string fmt_value(const float& value) { return fmt_number(value); }
template <>
inline std::string fmt_value(const int& value) { return fmt_integer(value); }
template <>
inline std::string fmt_value(const std::size_t& value) { return fmt_integer(static_cast<double>(value)); }
template <>
inline std::string fmt_value(const bool& value) { return value ? "true" : "false"; }
template <>
inline std::string fmt_value(const std::string& value) { return fmt_text(value); }
template <>
inline std::string fmt_value(const std::vector<double>& value) { return fmt_series(value); }
template <>
inline std::string fmt_value(const std::vector<int>& value) { return fmt_int_series(value); }
template <>
inline std::string fmt_value(const std::vector<std::vector<double>>& value) { return fmt_matrix(value); }

template <class T>
std::string fmt_value(const T&) {
    return "<not rendered>";
}

const std::vector<LabFormula>& lab_formulas();

// Executes formula `index` with the supplied inputs. Throws on invalid input.
std::string run_formula(std::size_t index, const LabInputs& in);

}  // namespace climate
